// A const member function that is NOT thread-safe without a mutex.
class Polynomial {
public:
  using RootsType = std::vector<double>;

  // This const method uses a mutex to protect mutable cache members.
  RootsType roots() const {
    std::lock_guard<std::mutex> g(m); // Lock before accessing mutable data
    if (!rootsAreValid) {
      // ... compute roots and store them in rootVals ...
      rootsAreValid = true;
    }
    return rootVals;
  } // Mutex is automatically unlocked here by lock_guard's destructor

private:
  // Mutex must be mutable to be locked/unlocked in a const method.
  mutable std::mutex m;
  mutable bool rootsAreValid{ false };
  mutable RootsType rootVals{};
};
